CREATE TABLE p2p_content_cache (
    id SERIAL PRIMARY KEY,
    peer_id INTEGER REFERENCES peers(id) ON DELETE CASCADE,
    content_hash VARCHAR(64) NOT NULL,
    content_type VARCHAR(32) NOT NULL,
    size_bytes BIGINT NOT NULL,
    file_name VARCHAR(255),
    metadata TEXT,
    added_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    last_accessed TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    access_count INTEGER DEFAULT 0
);

CREATE INDEX idx_p2p_cache_hash ON p2p_content_cache(content_hash);
CREATE INDEX idx_p2p_cache_peer ON p2p_content_cache(peer_id);
CREATE INDEX idx_p2p_cache_type ON p2p_content_cache(content_type);
CREATE INDEX idx_p2p_cache_last_accessed ON p2p_content_cache(last_accessed);

CREATE TABLE p2p_transfers (
    id SERIAL PRIMARY KEY,
    source_peer_id INTEGER REFERENCES peers(id) ON DELETE SET NULL,
    dest_device_id INTEGER REFERENCES devices(id) ON DELETE CASCADE,
    content_hash VARCHAR(64) NOT NULL,
    bytes_transferred BIGINT NOT NULL,
    transfer_time_ms INTEGER NOT NULL,
    completed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    success BOOLEAN NOT NULL DEFAULT TRUE,
    error_message TEXT
);

CREATE INDEX idx_p2p_transfers_time ON p2p_transfers(completed_at);
CREATE INDEX idx_p2p_transfers_source ON p2p_transfers(source_peer_id);
CREATE INDEX idx_p2p_transfers_dest ON p2p_transfers(dest_device_id);
CREATE INDEX idx_p2p_transfers_hash ON p2p_transfers(content_hash);
CREATE INDEX idx_p2p_transfers_success ON p2p_transfers(success);

CREATE TABLE rental_sessions (
    id SERIAL PRIMARY KEY,
    session_id VARCHAR(64) UNIQUE NOT NULL,
    host_device_id INTEGER REFERENCES devices(id) ON DELETE CASCADE,
    host_peer_id VARCHAR(64) REFERENCES peers(peer_id) ON DELETE SET NULL,
    renter_device_id INTEGER REFERENCES devices(id) ON DELETE CASCADE,
    renter_peer_id VARCHAR(64),
    rental_duration_hours INTEGER NOT NULL DEFAULT 24,
    start_time TIMESTAMP,
    end_time TIMESTAMP,
    payment_status VARCHAR(32) NOT NULL DEFAULT 'pending',
    payment_transaction_id VARCHAR(128),
    payment_amount DECIMAL(10, 2),
    payment_currency VARCHAR(10),
    session_status VARCHAR(32) NOT NULL DEFAULT 'pending',
    p2p_encryption_key TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_rental_sessions_session_id ON rental_sessions(session_id);
CREATE INDEX idx_rental_sessions_host ON rental_sessions(host_device_id);
CREATE INDEX idx_rental_sessions_renter ON rental_sessions(renter_device_id);
CREATE INDEX idx_rental_sessions_status ON rental_sessions(session_status);
CREATE INDEX idx_rental_sessions_payment ON rental_sessions(payment_status);
CREATE INDEX idx_rental_sessions_end_time ON rental_sessions(end_time);

CREATE TABLE rental_session_events (
    id SERIAL PRIMARY KEY,
    session_id VARCHAR(64) REFERENCES rental_sessions(session_id) ON DELETE CASCADE,
    event_type VARCHAR(64) NOT NULL,
    event_data JSONB,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX idx_rental_events_session ON rental_session_events(session_id);
CREATE INDEX idx_rental_events_type ON rental_session_events(event_type);
CREATE INDEX idx_rental_events_created ON rental_session_events(created_at);
